1	//! Apparatus-overhead calibration, dithered and amortized.
2	//!
3	//! Three constants, from two measurement passes:
4	//!
5	//! - **Dithered two-point fit** (mean-below-p99 at `N_LOW` /
6	//!   `N_HIGH`, random sub-quantum phase dither per sample):
7	//!   slope → `loop_per_iter_ns`, intercept → `frame_sample_ns`,
8	//!   the in-interval timer-pair slice a recorded sample actually
9	//!   contains. Both are subtracted from reported values.
10	//! - **Window pass** (min over amortized window means at `N_LOW`):
11	//!   with the dithered slope, yields `frame_call_ns`, the full
12	//!   call-to-call cost of taking a sample — sizes the experiment,
13	//!   never subtracted (most of it sits outside recorded
14	//!   intervals).
15	//!
16	//! Dither makes the ~10 ns clock quantum a zero-mean error that
17	//! averages away in means (validated on r5-7600x: frame_sample
18	//! repeats to ±0.06 ns within a frequency regime). See
19	//! notes/design.md#dithering-random-phase-injection and
20	//! notes/design.md#timer-overhead-in-interval-vs-call-to-call.
21	
22	use std::hint::black_box;
23	use std::time::{Duration, Instant};
24	
25	use crate::harness::Bench;
26	
27	/// Calibration warmup iterations — long enough for CPU frequency
28	/// boost to ramp before the first measurement.
29	pub const CAL_WARMUP: u64 = 100_000;
30	
31	/// Inner-loop count for the low-N calibration point.
32	pub const N_LOW: u64 = 100;
33	
34	/// Inner-loop count for the high-N calibration point. A wide spread
35	/// (`N_HIGH / (N_HIGH - N_LOW) ≈ 1.01`) keeps noise amplification on
36	/// the fitted intercept small.
37	pub const N_HIGH: u64 = 10_000;
38	
39	/// Samples per window in the call-to-call pass at [`N_LOW`]. The
40	/// window's ±1-quantum error divides by this: ~0.001 ns at a
41	/// ~10 ns quantum.
42	pub const W_LOW_SAMPLES: u64 = 10_000;
43	
44	/// Windows in the call-to-call pass; the minimum is kept. The min
45	/// sheds windows inflated by preemption or a frequency dip while
46	/// staying amortized (each candidate is already a window mean).
47	pub const W_LOW_WINDOWS: u64 = 100;
48	
49	/// Dither span in neutral spin iterations (~0.4-0.5 ns each →
50	/// ~26-32 ns, spanning ~3 clock quanta). A random 0..span delay
51	/// before each sample randomizes its phase on the ~10 ns clock
52	/// lattice, making the quantization error zero-mean (see
53	/// notes/design.md#dithering-random-phase-injection).
54	pub const DITHER_SPAN: u64 = 64;
55	
56	/// Dithered-fit windows per point (each yields one window mean;
57	/// the spread across windows is the dispersion signal).
58	pub const DITHER_WINDOWS: u64 = 20;
59	
60	/// Dithered-fit samples per window at [`N_LOW`].
61	pub const DITHER_LOW_SAMPLES: u64 = 5_000;
62	
63	/// Dithered-fit samples per window at [`N_HIGH`] (samples are
64	/// ~100× longer, so fewer keep the wall cost comparable).
65	pub const DITHER_HIGH_SAMPLES: u64 = 500;
66	
67	/// Xorshift64* PRNG for dither lengths. No external dep; phase
68	/// randomization needs rough uniformity, not statistical rigor.
69	struct XorShift64(u64);
70	
71	impl XorShift64 {
72	    /// Next pseudo-random u64.
73	    fn next(&mut self) -> u64 {
74	        let mut x = self.0;
75	        x ^= x >> 12;
76	        x ^= x << 25;
77	        x ^= x >> 27;
78	        self.0 = x;
79	        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
80	    }
81	}
82	
83	/// Sub-quantum phase dither: a random 0..[`DITHER_SPAN`] neutral
84	/// spin, run *outside* the timed interval before each sample.
85	/// Used by calibration and by the harness sample seam.
86	pub struct Dither(XorShift64);
87	
88	impl Dither {
89	    /// New dither source, seeded from wall-clock nanos (any
90	    /// per-invocation variation suffices for phase dither).
91	    pub fn new() -> Self {
92	        let seed = std::time::SystemTime::now()
93	            .duration_since(std::time::UNIX_EPOCH)
94	            .map(|d| d.subsec_nanos() as u64 | 1)
95	            .unwrap_or(0x9E37_79B9_7F4A_7C15); // OK: fixed fallback seed still dithers
96	        Dither(XorShift64(seed))
97	    }
98	
99	    /// Spin a random 0..[`DITHER_SPAN`] iterations to re-roll the
100	    /// next sample's phase on the clock lattice.
101	    #[inline]
102	    pub fn spin(&mut self) {
103	        let r = self.0.next() % DITHER_SPAN;
104	        for _ in 0..r {
105	            black_box(1u64);
106	        }
107	    }
108	
109	    /// Next raw pseudo-random u64, for callers needing coarser
110	    /// randomness (e.g. the harness's block sleep lengths).
111	    pub fn rand_u64(&mut self) -> u64 {
112	        self.0.next()
113	    }
114	}
115	
116	impl Default for Dither {
117	    /// Same as [`Dither::new`].
118	    fn default() -> Self {
119	        Self::new()
120	    }
121	}
122	
123	/// Aggregates of one dithered measurement point (all ns):
124	/// linear statistics that keep the dither win, plus min for
125	/// reference against the lattice floor.
126	#[derive(Debug)]
127	pub struct DitherPoint {
128	    /// Full mean over all samples — unbiased under dither but
129	    /// absorbs interrupt spikes.
130	    pub mean_ns: f64,
131	    /// Mean of samples ≤ p99 — sheds one-sided interrupt
132	    /// contamination at a small estimable bias. The fit input.
133	    pub mean_p99_ns: f64,
134	    /// Median of per-window means — robust to a bad window
135	    /// without snapping (window means are not lattice-valued).
136	    pub median_window_ns: f64,
137	    /// Spread (max − min) of the window means — a dispersion
138	    /// signal for a CI and for regime-shift detection.
139	    pub window_spread_ns: f64,
140	    /// Minimum sample — the lattice floor, for comparison.
141	    pub min_ns: u64,
142	}
143	
144	/// Apparatus-overhead model fitted by [`calibrate`].
145	#[derive(Debug)]
146	pub struct Overhead {
147	    /// Call-to-call cost of taking one sample (full timer-pair
148	    /// apparatus cost, clock-read latencies included), in ns.
149	    /// Sizes the experiment ([`crate::harness`]'s `pick_inner`);
150	    /// most of it sits *outside* recorded intervals, so it is
151	    /// never subtracted from reported values.
152	    pub frame_call_ns: f64,
153	    /// In-interval timer-pair slice a recorded sample contains,
154	    /// in ns — the dithered fit's intercept. Subtracted per
155	    /// sample (amortized by `inner`); see
156	    /// [`Overhead::adjust_per_call_ns`].
157	    pub frame_sample_ns: f64,
158	    /// Per-inner-iteration loop overhead (branch + `black_box`),
159	    /// in ns — the dithered fit's slope. Subtracted per call.
160	    /// Also the frequency-regime fingerprint (repeats to 5
161	    /// significant figures within a regime).
162	    pub loop_per_iter_ns: f64,
163	    /// Raw call-to-call window minimum at [`N_LOW`] (ns).
164	    /// Preserved for `-v` logging and cache provenance.
165	    pub cal_w_low_ns: f64,
166	    /// Raw dithered point at [`N_LOW`].
167	    pub cal_d_low: DitherPoint,
168	    /// Raw dithered point at [`N_HIGH`].
169	    pub cal_d_high: DitherPoint,
170	    /// Wall-clock duration of the full calibration run.
171	    pub cal_duration: Duration,
172	}
173	
174	impl Overhead {
175	    /// Per-call apparatus overhead subtracted from reported values,
176	    /// in ns: the amortized loop cost plus the in-interval framing
177	    /// slice amortized by `inner`.
178	    ///
179	    /// - `frame_sample_ns` is the dithered-fit intercept — the
180	    ///   slice of timer cost recorded intervals actually contain
181	    ///   (±~0.1 ns run-to-run within a frequency regime), not the
182	    ///   call-to-call cost, most of which falls outside them.
183	    pub fn adjust_per_call_ns(&self, inner: u64) -> f64 {
184	        self.frame_sample_ns / inner as f64 + self.loop_per_iter_ns
185	    }
186	}
187	
188	struct EmptyBench;
189	
190	impl Bench for EmptyBench {
191	    fn name(&self) -> &str {
192	        "empty"
193	    }
194	
195	    fn step(&mut self) -> u64 {
196	        black_box(1)
197	    }
198	}
199	
200	/// Run the dithered two-point calibration plus the call-to-call
201	/// window pass and return the fitted [`Overhead`]. Blocks for
202	/// ~150-200 ms on a typical modern x86; logs raw points and the
203	/// alternative fits at debug level.
204	pub fn calibrate() -> Overhead {
205	    let mut bench = EmptyBench;
206	    let mut dither = Dither::new();
207	    let cal_start = Instant::now();
208	    for _ in 0..CAL_WARMUP {
209	        black_box(bench.step());
210	    }
211	
212	    let d_low = dither_measure(&mut dither, DITHER_WINDOWS, DITHER_LOW_SAMPLES, N_LOW);
213	    let d_high = dither_measure(&mut dither, DITHER_WINDOWS, DITHER_HIGH_SAMPLES, N_HIGH);
214	    log_dither_point("d_low", &d_low);
215	    log_dither_point("d_high", &d_high);
216	    log_alt_fits(&d_low, &d_high);
217	
218	    // The production fit uses mean-below-p99 at both points — the
219	    // tightest aggregation in validation (r5-7600x: frame_sample
220	    // 8.2 ± 0.06 ns, slope stable to 5 significant figures).
221	    let (frame_raw, loop_per_iter_ns) = two_point_fit(d_low.mean_p99_ns, d_high.mean_p99_ns);
222	    let frame_sample_ns = frame_raw.max(0.0);
223	
224	    // Call-to-call: one window pass at N_LOW; the dithered slope
225	    // supplies the loop share (better measured than a second
226	    // window point would be).
227	    let w_low = measure_window(&mut bench, W_LOW_WINDOWS, W_LOW_SAMPLES, N_LOW);
228	    let frame_call_ns = (w_low - N_LOW as f64 * loop_per_iter_ns).max(0.0);
229	
230	    Overhead {
231	        frame_call_ns,
232	        frame_sample_ns,
233	        loop_per_iter_ns,
234	        cal_w_low_ns: w_low,
235	        cal_d_low: d_low,
236	        cal_d_high: d_high,
237	        cal_duration: cal_start.elapsed(),
238	    }
239	}
240	
241	/// Measure one dithered point: `windows` windows of `samples`
242	/// samples at the given `inner`, each sample preceded by a random
243	/// sub-quantum [`Dither::spin`] outside the timed interval.
244	fn dither_measure(dither: &mut Dither, windows: u64, samples: u64, inner: u64) -> DitherPoint {
245	    let mut bench = EmptyBench;
246	    let mut all: Vec<u64> = Vec::with_capacity((windows * samples) as usize);
247	    let mut window_means: Vec<f64> = Vec::with_capacity(windows as usize);
248	    for _ in 0..windows {
249	        let mut sum: u128 = 0;
250	        for _ in 0..samples {
251	            dither.spin();
252	            let start = Instant::now();
253	            for _ in 0..inner {
254	                black_box(bench.step());
255	            }
256	            let e = start.elapsed().as_nanos() as u64;
257	            sum += u128::from(e);
258	            all.push(e);
259	        }
260	        window_means.push(sum as f64 / samples as f64);
261	    }
262	
263	    all.sort_unstable();
264	    let n = all.len();
265	    let mean_ns = all.iter().map(|&v| v as f64).sum::<f64>() / n as f64;
266	    let n99 = (n as f64 * 0.99).ceil() as usize;
267	    let mean_p99_ns = all[..n99].iter().map(|&v| v as f64).sum::<f64>() / n99 as f64;
268	
269	    window_means.sort_unstable_by(|a, b| a.total_cmp(b));
270	    let median_window_ns = window_means[window_means.len() / 2];
271	    let window_spread_ns = window_means[window_means.len() - 1] - window_means[0];
272	
273	    DitherPoint {
274	        mean_ns,
275	        mean_p99_ns,
276	        median_window_ns,
277	        window_spread_ns,
278	        min_ns: all[0],
279	    }
280	}
281	
282	/// Amortized per-sample cost at a given `inner`: each window times
283	/// `samples` complete samples (timer pair around an `inner`-iteration
284	/// loop — the exact shape the harness takes one at a time) and
285	/// divides by the count, so quantization error is q/samples; the
286	/// minimum over `windows` windows is returned, in ns.
287	fn measure_window(bench: &mut EmptyBench, windows: u64, samples: u64, inner: u64) -> f64 {
288	    let mut min_ns = f64::INFINITY;
289	    for _ in 0..windows {
290	        let window = Instant::now();
291	        for _ in 0..samples {
292	            let start = Instant::now();
293	            for _ in 0..inner {
294	                black_box(bench.step());
295	            }
296	            black_box(start.elapsed());
297	        }
298	        let per_sample = window.elapsed().as_nanos() as f64 / samples as f64;
299	        if per_sample < min_ns {
300	            min_ns = per_sample;
301	        }
302	    }
303	    min_ns
304	}
305	
306	/// Two-point linear fit over the [`N_LOW`] / [`N_HIGH`] pair,
307	/// shared by the production fit, the alternative-fit logging, and
308	/// the `calibrate` command's diagnostic output. Returns
309	/// `(intercept_ns, slope_ns)`; the slope clamps to 0 when the
310	/// points invert, and the intercept is left unclamped (a negative
311	/// value is itself a diagnostic signal).
312	pub fn two_point_fit(low_ns: f64, high_ns: f64) -> (f64, f64) {
313	    let slope = if high_ns > low_ns {
314	        (high_ns - low_ns) / (N_HIGH - N_LOW) as f64
315	    } else {
316	        0.0
317	    };
318	    (low_ns - N_LOW as f64 * slope, slope)
319	}
320	
321	/// Debug-log one dithered point's aggregates.
322	fn log_dither_point(name: &str, p: &DitherPoint) {
323	    log::debug!(
324	        "dither {name}: mean={:.4} p99mean={:.4} medwin={:.4} spread={:.4} min={} ns",
325	        p.mean_ns,
326	        p.mean_p99_ns,
327	        p.median_window_ns,
328	        p.window_spread_ns,
329	        p.min_ns,
330	    );
331	}
332	
333	/// Debug-log the three alternative fits (full / p99 / medwin) so
334	/// estimator agreement stays observable run to run; `p99` is the
335	/// production fit.
336	fn log_alt_fits(d_low: &DitherPoint, d_high: &DitherPoint) {
337	    for (kind, low, high) in [
338	        ("full", d_low.mean_ns, d_high.mean_ns),
339	        ("p99", d_low.mean_p99_ns, d_high.mean_p99_ns),
340	        ("medwin", d_low.median_window_ns, d_high.median_window_ns),
341	    ] {
342	        let (intercept, slope) = two_point_fit(low, high);
343	        log::debug!(
344	            "dither fit({kind}): in-interval framing={intercept:.4} ns, loop_per_iter={slope:.6} ns"
345	        );
346	    }
347	}
348

