//! Standalone replica of iiac-perf's two calibration passes, to
//! explain why in a debug build the window pass (`w_low`) comes in
//! *below* the dithered pass's per-sample interval — physically
//! impossible if both loops run at the same speed.
//!
//! Variants, all at inner=100, same sample budget:
//!
//! - `loop_only`   — outer timer only, no per-sample timer pair:
//!                   the pure loop cost, the baseline everything
//!                   else is measured against.
//! - `window`      — measure_window replica (outer timer, inner
//!                   timer pair discarded via black_box).
//! - `dith`        — dither_measure replica (spin + push).
//! - `dith_nospin` — push, no spin.
//! - `dith_nopush` — spin, no push.
//! - `bare`        — neither: minimal per-sample body.
//!
//! Each variant reports both min-over-windows and mean-below-p99
//! so estimator choice is separable from measurement style. Rounds
//! run forward then reversed, so a CPU-frequency ramp shows up as
//! an order effect rather than a variant effect.

use std::hint::black_box;
use std::time::Instant;

const INNER: u64 = 100;
const SAMPLES: u64 = 5_000;
const WINDOWS: u64 = 20;
const DITHER_SPAN: u64 = 64;
const WARMUP: u64 = 100_000;

struct XorShift64(u64);

impl XorShift64 {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
}

struct EmptyBench;

impl EmptyBench {
    fn step(&mut self) -> u64 {
        black_box(1)
    }
}

/// One variant's result, all ns per sample (i.e. per INNER-iteration
/// loop, whatever framing that variant adds).
struct Stats {
    /// Min over window means — the `w_low` estimator.
    win_min: f64,
    /// Mean over window means.
    win_mean: f64,
    /// Mean of per-sample values below p99 — the dithered-fit
    /// estimator. NaN for variants with no per-sample timer.
    samp_p99: f64,
    /// Min single per-sample value. NaN when not applicable.
    samp_min: f64,
}

fn summarize(window_means: Vec<f64>, mut samples: Vec<u64>) -> Stats {
    let win_min = window_means.iter().copied().fold(f64::INFINITY, f64::min);
    let win_mean = window_means.iter().sum::<f64>() / window_means.len() as f64;
    if samples.is_empty() {
        return Stats { win_min, win_mean, samp_p99: f64::NAN, samp_min: f64::NAN };
    }
    samples.sort_unstable();
    let n99 = (samples.len() as f64 * 0.99).ceil() as usize;
    let samp_p99 = samples[..n99].iter().map(|&v| v as f64).sum::<f64>() / n99 as f64;
    Stats { win_min, win_mean, samp_p99, samp_min: samples[0] as f64 }
}

/// Pure loop cost: outer timer around SAMPLES repetitions of the
/// INNER-iteration loop, with no per-sample timer pair at all.
fn loop_only(bench: &mut EmptyBench) -> Stats {
    let mut window_means = Vec::new();
    for _ in 0..WINDOWS {
        let window = Instant::now();
        for _ in 0..SAMPLES {
            for _ in 0..INNER {
                black_box(bench.step());
            }
        }
        window_means.push(window.elapsed().as_nanos() as f64 / SAMPLES as f64);
    }
    summarize(window_means, Vec::new())
}

/// `measure_window` replica: outer timer, per-sample timer pair
/// taken and discarded.
fn window(bench: &mut EmptyBench) -> Stats {
    let mut window_means = Vec::new();
    for _ in 0..WINDOWS {
        let window = Instant::now();
        for _ in 0..SAMPLES {
            let start = Instant::now();
            for _ in 0..INNER {
                black_box(bench.step());
            }
            black_box(start.elapsed());
        }
        window_means.push(window.elapsed().as_nanos() as f64 / SAMPLES as f64);
    }
    summarize(window_means, Vec::new())
}

/// `dither_measure` replica, with spin and push independently
/// switchable. Window means here are computed the same way the
/// window pass computes them (outer timer / SAMPLES) so the two
/// styles are directly comparable, *and* the per-sample interval
/// values are collected as dither_measure does.
fn per_sample(bench: &mut EmptyBench, rng: &mut XorShift64, spin: bool, push: bool) -> Stats {
    let mut window_means = Vec::new();
    let mut all: Vec<u64> = Vec::with_capacity((WINDOWS * SAMPLES) as usize);
    let mut sink: Vec<u64> = Vec::with_capacity((WINDOWS * SAMPLES) as usize);
    for _ in 0..WINDOWS {
        let mut sum: u128 = 0;
        let window = Instant::now();
        for _ in 0..SAMPLES {
            if spin {
                let r = rng.next() % DITHER_SPAN;
                for _ in 0..r {
                    black_box(1u64);
                }
            }
            let start = Instant::now();
            for _ in 0..INNER {
                black_box(bench.step());
            }
            let e = start.elapsed().as_nanos() as u64;
            sum += u128::from(e);
            if push {
                sink.push(e);
            }
            all.push(e);
        }
        let _ = sum;
        window_means.push(window.elapsed().as_nanos() as f64 / SAMPLES as f64);
    }
    black_box(&sink);
    summarize(window_means, all)
}

fn header() {
    println!(
        "{:<12} {:>12} {:>12} {:>12} {:>12}",
        "variant", "win_min", "win_mean", "samp_p99", "samp_min"
    );
}

fn row(name: &str, s: &Stats) {
    println!(
        "{:<12} {:>12.2} {:>12.2} {:>12.2} {:>12.2}",
        name, s.win_min, s.win_mean, s.samp_p99, s.samp_min
    );
}

fn main() {
    let mut bench = EmptyBench;
    let mut rng = XorShift64(0x9E37_79B9_7F4A_7C15);

    for _ in 0..WARMUP {
        black_box(bench.step());
    }

    let names = ["loop_only", "window", "dith", "dith_nospin", "dith_nopush", "bare"];
    let rounds: [(&str, bool); 2] = [("forward", false), ("reversed", true)];

    for (label, rev) in rounds {
        println!("\n=== round: {label} (inner={INNER}, {WINDOWS}x{SAMPLES}) ===");
        header();
        let mut idx: Vec<usize> = (0..names.len()).collect();
        if rev {
            idx.reverse();
        }
        for i in idx {
            let s = match i {
                0 => loop_only(&mut bench),
                1 => window(&mut bench),
                2 => per_sample(&mut bench, &mut rng, true, true),
                3 => per_sample(&mut bench, &mut rng, false, true),
                4 => per_sample(&mut bench, &mut rng, true, false),
                _ => per_sample(&mut bench, &mut rng, false, false),
            };
            row(names[i], &s);
        }
    }
}

