/// switchable, plus an outer window timer so the same sample stream
/// yields both the in-interval mean and the call-to-call cost.
/// Logs `(p99mean, min, call_to_call)`. Remove before commit.
fn dither_probe(dither: &mut Dither, name: &str, spin: bool, push: bool) {
    let mut bench = EmptyBench;
    let mut all: Vec<u64> = Vec::with_capacity((DITHER_WINDOWS * DITHER_LOW_SAMPLES) as usize);
    let mut win_min = f64::INFINITY;
    for _ in 0..DITHER_WINDOWS {
        let window = Instant::now();
        for _ in 0..DITHER_LOW_SAMPLES {
            if spin {
                dither.spin();
            }
            let start = Instant::now();
            for _ in 0..N_LOW {
                black_box(bench.step());
            }
            let e = start.elapsed().as_nanos() as u64;
            if push {
                all.push(e);
            } else {
                black_box(e);
            }
        }
        let per = window.elapsed().as_nanos() as f64 / DITHER_LOW_SAMPLES as f64;
        if per < win_min {
            win_min = per;
        }
    }
    if all.is_empty() {
        log::debug!("PROBE dither[{name}]: call_to_call_min={win_min:.4} ns (no samples kept)");
        return;
    }
    all.sort_unstable();
    let n99 = (all.len() as f64 * 0.99).ceil() as usize;
    let p99 = all[..n99].iter().map(|&v| v as f64).sum::<f64>() / n99 as f64;
    log::debug!(
        "PROBE dither[{name}]: p99mean={p99:.4} min={} call_to_call_min={win_min:.4} ns",
        all[0],
    );
}

