input.new_string:
/// Dithered-fit windows per point (each yields one window mean;
/// the spread across windows is the dispersion signal).
///
/// - Raised from 20 with the per-window sample counts halved, so
///   the total sample budget is unchanged: the fit now reads the
///   *lower tail* of the window means (see
///   [`DITHER_FAST_WINDOWS`]), which needs windows to choose
///   among, not samples per window.
/// - Shorter windows also catch less interference each, so more
///   of them come through clean.
pub const DITHER_WINDOWS: u64 = 40;

/// Dithered-fit samples per window at [`N_LOW`].
pub const DITHER_LOW_SAMPLES: u64 = 2_500;

/// Dithered-fit samples per window at [`N_HIGH`] (samples are
/// ~100× longer, so fewer keep the wall cost comparable).
pub const DITHER_HIGH_SAMPLES: u64 = 250;

/// Window means averaged for the production fit — the fastest
/// [`DITHER_FAST_WINDOWS`] of [`DITHER_WINDOWS`], i.e. the lower
/// 10%.
///
/// - Scheduler interference is one-sided (it can only add time)
///   and duration-proportional, so it inflates the `N_HIGH`
///   point far harder than `N_LOW`, tilting the fitted slope up
///   and levering the intercept negative. A lower-tail estimator
///   sheds it; trimming 1% off the top does not. See
///   notes/chores/chores-04.md#one-sided-contamination-and-the-two-point-fit.
/// - Averaging *window means* rather than raw samples keeps the
///   dither win: quantization is already averaged away inside
///   each window, so the tail selection is not selecting on
///   lattice luck.
pub const DITHER_FAST_WINDOWS: u64 = 4;

